implementation.source:
// Column index of the matrix m for column vectors (the GLSL m[index]), whatever the matrix
// convention of the language.
float4 splatColumn(float4x4 m, int index)
{
    float4 e = float4(index == 0 ? 1.0 : 0.0, index == 1 ? 1.0 : 0.0, index == 2 ? 1.0 : 0.0,
        index == 3 ? 1.0 : 0.0);
    return mul(m, e);
}

void splatGeometryInstanced(
    AttribArray<geometryInS> inputs,
    float4x4 viewProjection,
    float2 viewportPixelSize,
    float2 quadPosition[4],
    float3 cameraPosition,
    float shDegree,
    float shTexelsPerSplat,
    float fixedQuadSize)
{
    geometryInS outS = inputs[0];

    // Columns of the view projection matrix for column vectors.
    float4 c0 = splatColumn(viewProjection, 0);
    float4 c1 = splatColumn(viewProjection, 1);
    float4 c2 = splatColumn(viewProjection, 2);
    float4 c3 = splatColumn(viewProjection, 3);

    // Linear part of the instance matrix (world matrix of the prim included), as columns, and the
    // world position of the splat center.
    float3 l0 = outS.ZZZZinstancePosMtx0.xyz;
    float3 l1 = outS.ZZZZinstancePosMtx1.xyz;
    float3 l2 = outS.ZZZZinstancePosMtx2.xyz;
    float3 center = outS.Pm;

    // Per-splat frustum cull on the center, OpenGL clip volume: -w <= z <= w.
    float4 clip = c0 * center.x + c1 * center.y + c2 * center.z + c3;
    if (clip.w <= 1.0e-6 || abs(clip.x) > clip.w || abs(clip.y) > clip.w
        || clip.z < -clip.w || clip.z > clip.w)
        return;

    // Rotation of the splat (identity when the quaternion is degenerate). Columns of the matrix.
    float4 q = outS.splatOrientation;
    float qLength = length(q);
    if (qLength > 1.0e-6)
        q = q / qLength;
    else
        q = float4(0.0, 0.0, 0.0, 1.0);
    float xx = q.x * q.x, yy = q.y * q.y, zz = q.z * q.z;
    float xy = q.x * q.y, xz = q.x * q.z, yz = q.y * q.z;
    float wx = q.w * q.x, wy = q.w * q.y, wz = q.w * q.z;
    float3 r0 = float3(1.0 - 2.0 * (yy + zz), 2.0 * (xy + wz), 2.0 * (xz - wy));
    float3 r1 = float3(2.0 * (xy - wz), 1.0 - 2.0 * (xx + zz), 2.0 * (yz + wx));
    float3 r2 = float3(2.0 * (xz + wy), 2.0 * (yz - wx), 1.0 - 2.0 * (xx + yy));

    // Ellipsoid axes in world space: the semi-axes, scaled.
    float3 scale = outS.splatScaleOpacity.xyz;
    float3 axis0 = (l0 * r0.x + l1 * r0.y + l2 * r0.z) * scale.x;
    float3 axis1 = (l0 * r1.x + l1 * r1.y + l2 * r1.z) * scale.y;
    float3 axis2 = (l0 * r2.x + l1 * r2.y + l2 * r2.z) * scale.z;

    // Jacobian of the NDC position with respect to the world-space position. c0..c3 are the
    // columns of the view projection matrix for column vectors.
    float invW = 1.0 / clip.w;
    float3 dClipW = float3(c0.w, c1.w, c2.w);
    float3 jacobianX = float3(c0.x, c1.x, c2.x) * invW - dClipW * (clip.x * invW * invW);
    float3 jacobianY = float3(c0.y, c1.y, c2.y) * invW - dClipW * (clip.y * invW * invW);
    float3 rowX = float3(dot(jacobianX, axis0), dot(jacobianX, axis1), dot(jacobianX, axis2));
    float3 rowY = float3(dot(jacobianY, axis0), dot(jacobianY, axis1), dot(jacobianY, axis2));

    // Covariance of the projected ellipse in NDC, with a 0.3 pixel low-pass so that tiny
    // splats keep a visible footprint.
    float2 lowPass = 0.6 / viewportPixelSize;
    float covXX = dot(rowX, rowX) + lowPass.x * lowPass.x;
    float covXY = dot(rowX, rowY);
    float covYY = dot(rowY, rowY) + lowPass.y * lowPass.y;

    // Eigen decomposition: the half axes of the quad are the standard deviations.
    float mid = 0.5 * (covXX + covYY);
    float radius = sqrt(max(0.25 * (covXX - covYY) * (covXX - covYY) + covXY * covXY, 0.0));
    float lambda1 = mid + radius;
    float lambda2 = max(mid - radius, 0.0);
    // Both expressions are eigenvectors of lambda1, take the better conditioned one.
    float2 directionA = float2(lambda1 - covYY, covXY);
    float2 directionB = float2(covXY, lambda1 - covXX);
    float2 direction1 = directionB;
    if (dot(directionA, directionA) >= dot(directionB, directionB))
        direction1 = directionA;
    float directionLength = length(direction1);
    if (directionLength > 1.0e-30)
        direction1 = direction1 / directionLength;
    else
        direction1 = float2(1.0, 0.0);
    float2 direction2 = float2(-direction1.y, direction1.x);
    float extent1 = sqrt(lambda1);
    float extent2 = sqrt(lambda2);

    // Color: the SH0 stream (the SH texture cannot be read in Cg).
    float3 rgb = outS.splatColor.rgb;

    for (int i = 0; i < 4; ++i)
    {
        float2 corner = quadPosition[i] * 2.0;
        float2 offsetNdc = direction1 * (corner.x * extent1) + direction2 * (corner.y * extent2);
        if (fixedQuadSize > 0.0)
            // Axis-aligned square of fixedQuadSize pixels, whatever the scale and rotation.
            offsetNdc = corner * (fixedQuadSize / viewportPixelSize);
        outS.Pc = float4(clip.xy + offsetNdc * clip.w, clip.zw);
        outS.ColorFromGS = float4(rgb, 1.0);
        outS.UVFromGS = float3(corner, outS.splatScaleOpacity.w);
        emitVertex(outS);
    }
    restartStrip();
}
